// Node.js版本检测
const [major] = process.version.slice(1).split('.').map(Number);
if (major < 18) {
  console.error(
    "错误：需要 Node.js 18 或更高版本才能运行此程序\n" +
      "当前 Node.js 版本: " + process.version + "\n" +
      "请升级 Node.js 到 18.20.8 或以上版本",
  );
  process.exit(1);
}

// 辅助函数：安全地获取错误信息，不包含堆栈
function getSimpleErrorMessage(error) {
  if (error instanceof Error) {
    return error.message || String(error);
  }
  if (error && typeof error === "object") {
    return error.message || JSON.stringify(error);
  }
  return String(error);
}

// 全局错误处理 - 完全抑制堆栈跟踪，只输出简洁错误信息
process.on("uncaughtException", (err) => {
  console.error(`错误信息：${getSimpleErrorMessage(err)}`);
  setTimeout(() => process.exit(1), 100);
});

// 处理 Promise 未捕获错误
process.on("unhandledRejection", (reason, promise) => {
  console.error(`错误信息：${getSimpleErrorMessage(reason)}`);
  setTimeout(() => process.exit(1), 100);
});
